/* Finite State Machine (FSM) representation for the embedded controller requirements */

/* States */
State Idle;
State Inspiration;
State Expiration;
State Measurement;

/* Events */
Event TriggerInspiration;
Event TriggerExpiration;
Event MeasurePEEP;
Event PressureBelowThreshold;
Event PressureAboveThreshold;
Event BreathRateExceeded;

/* Transitions with guards */
Transition Idle --> Inspiration
    Guard: TriggerInspiration
    Action: InitiateInspirationCycle;

Transition Inspiration --> Expiration
    Guard: InspirationCycleComplete
    Action: EndInspirationCycle;

Transition Expiration --> Idle
    Guard: ExpirationCycleComplete
    Action: PrepareNextCycle;

Transition Idle --> Measurement
    Guard: MeasurePEEPRequested
    Action: StartPEEPMeasurement;

Transition Measurement --> Idle
    Guard: PEEPMeasured
    Action: RecordPEEPValue;

/* Additional guards for pressure limits */
Guard PressureBelowThresholdGuard
    Condition: MeasuredPressure < -4cm;
Guard PressureAboveThresholdGuard
    Condition: MeasuredPressure > 60cm;

/* Lifecycle */
InitialState: Idle;

/* Requirements mapping */
[RW-SW-4] => PressureBelowThresholdGuard;
[RW-SW-7] => PressureAboveThresholdGuard;
[RW-SW-52] => MeasurePEEP;
[RW-SW-55] => Within10PercentTargetGuard;
[RW-SW-56] => TriggerInspiration;
[RW-SW-57] => TriggerExpiration;
[RW-SW-59] => PIPTargetGuard;
[RW-SW-62] => BreathRateTargetGuard;
```

